ALTER TYPE "public"."ops_alert_kind" ADD VALUE 'confidential_balance_mismatch';--> statement-breakpoint
ALTER TABLE "intent_quotes" DROP CONSTRAINT "intent_quotes_send_is_from_company_wallet";--> statement-breakpoint
ALTER TABLE "wallet_transactions" DROP CONSTRAINT "wallet_transactions_deposit_is_onchain";--> statement-breakpoint
ALTER TABLE "wallet_transactions" DROP CONSTRAINT "wallet_transactions_quote_link_is_treasury";--> statement-breakpoint
ALTER TABLE "wallet_transactions" DROP CONSTRAINT "wallet_transactions_near_deposit_has_receipt";--> statement-breakpoint
ALTER TABLE "intent_quotes" ADD COLUMN "ledger_credited_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "wallets" ADD COLUMN "confidential_usdc" bigint;--> statement-breakpoint
ALTER TABLE "wallets" ADD COLUMN "confidential_usdc_read_at" timestamp with time zone;--> statement-breakpoint
CREATE INDEX "intent_quotes_ledger_credit_due_idx" ON "intent_quotes" USING btree ("settled_at") WHERE "intent_quotes"."recipient_type" = 'CONFIDENTIAL_INTENTS' AND "intent_quotes"."status" = 'succeeded' AND "intent_quotes"."ledger_credited_at" IS NULL;--> statement-breakpoint
CREATE UNIQUE INDEX "wallet_transactions_quote_settled_credit_unique" ON "wallet_transactions" USING btree ("intent_quote_id") WHERE "wallet_transactions"."intent_quote_id" IS NOT NULL AND "wallet_transactions"."tx_hash" IS NULL AND "wallet_transactions"."usdc_amount" > 0;--> statement-breakpoint
ALTER TABLE "intent_quotes" ADD CONSTRAINT "intent_quotes_recipient_type_matches_purpose" CHECK (("intent_quotes"."recipient_type" = 'DESTINATION_CHAIN' OR "intent_quotes"."purpose"::text IN ('move_in', 'fund_in', 'invoice_payment', 'fund_in_return')) AND ("intent_quotes"."purpose"::text <> 'move_in' OR "intent_quotes"."recipient_type" = 'CONFIDENTIAL_INTENTS'));--> statement-breakpoint
ALTER TABLE "intent_quotes" ADD CONSTRAINT "intent_quotes_ledger_credit_is_confidential_delivery" CHECK ("intent_quotes"."ledger_credited_at" IS NULL OR ("intent_quotes"."status" = 'succeeded' AND "intent_quotes"."recipient_type" = 'CONFIDENTIAL_INTENTS' AND "intent_quotes"."purpose"::text IN ('fund_in', 'invoice_payment', 'fund_in_return')));--> statement-breakpoint
ALTER TABLE "intent_quotes" ADD CONSTRAINT "intent_quotes_send_is_from_company_wallet" CHECK ("intent_quotes"."company_wallet_send_id" IS NULL OR "intent_quotes"."purpose"::text IN ('base_hop', 'usdc_payout', 'fund_in_return', 'to_treasury', 'move_in'));--> statement-breakpoint
ALTER TABLE "wallet_transactions" ADD CONSTRAINT "wallet_transactions_deposit_has_source" CHECK ("wallet_transactions"."type" <> 'deposit' OR ("wallet_transactions"."intent_quote_id" IS NULL AND "wallet_transactions"."tx_hash" IS NOT NULL AND "wallet_transactions"."log_index" IS NOT NULL AND "wallet_transactions"."block_number" IS NOT NULL) OR ("wallet_transactions"."intent_quote_id" IS NOT NULL AND "wallet_transactions"."chain" <> 'base' AND "wallet_transactions"."tx_hash" IS NULL AND "wallet_transactions"."receipt_id" IS NULL AND "wallet_transactions"."log_index" IS NULL AND "wallet_transactions"."transfer_index" IS NULL AND "wallet_transactions"."block_number" IS NULL));--> statement-breakpoint
ALTER TABLE "wallet_transactions" ADD CONSTRAINT "wallet_transactions_quote_link_is_treasury" CHECK (("wallet_transactions"."type"::text = 'to_treasury') <= ("wallet_transactions"."intent_quote_id" IS NOT NULL) AND ("wallet_transactions"."intent_quote_id" IS NULL OR "wallet_transactions"."type"::text IN ('to_treasury', 'from_treasury', 'deposit')));--> statement-breakpoint
ALTER TABLE "wallet_transactions" ADD CONSTRAINT "wallet_transactions_near_deposit_has_receipt" CHECK ("wallet_transactions"."chain" = 'base' OR "wallet_transactions"."type" <> 'deposit' OR "wallet_transactions"."receipt_id" IS NOT NULL OR "wallet_transactions"."intent_quote_id" IS NOT NULL);--> statement-breakpoint
ALTER TABLE "wallets" ADD CONSTRAINT "wallets_confidential_reading_is_whole" CHECK (("wallets"."confidential_usdc" IS NULL) = ("wallets"."confidential_usdc_read_at" IS NULL));